D-M-NoHearts.css:
body{margin:0;font-family:'Baloo 2',-apple-system,BlinkMacSystemFont,'PingFang SC','Hiragino Sans GB','Microsoft YaHei','HarmonyOS Sans SC','MiSans',system-ui,sans-serif;background:#141312;color:#F2EFEA}
a{color:#FFB27A;text-decoration:none}a:hover{color:#FFC9A3}
button,a{transition:transform .12s ease,box-shadow .15s ease,filter .15s ease,background-color .15s ease}
button:not(:disabled):active,a:active{transform:translateY(1px) scale(.99)}
button:focus-visible,a:focus-visible{outline:3px solid #6C63FF;outline-offset:3px}
h1,h2,h3{line-height:1.25;letter-spacing:-0.01em;text-wrap:balance;margin:0}p{line-height:1.6;margin:0}
body{-webkit-font-smoothing:antialiased;font-variant-numeric:tabular-nums}
@keyframes pp-toast{from{opacity:0;transform:translate(-50%,8px)}to{opacity:1;transform:translate(-50%,0)}}
@keyframes pp-shimmer{0%{background-position:-300px 0}100%{background-position:300px 0}}
@keyframes pp-spin{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){[style*="pp-shimmer"],[style*="pp-spin"],[style*="pp-toast"]{animation:none!important}}
/*pp-mg*/a[style*="inset 0 -4px 0 rgba("]:active,button[style*="inset 0 -4px 0 rgba("]:not(:disabled):active{transform:scale(.96)!important;filter:brightness(.97)!important}.mg-nav a:active .mg-ni{transform:scale(.9)}@keyframes mg-pop{0%{transform:scale(.4);opacity:0}70%{transform:scale(1.08)}100%{transform:scale(1);opacity:1}}.mg-pop{animation:mg-pop .55s cubic-bezier(.3,1.4,.5,1) both}@keyframes mg-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}.mg-float{animation:mg-float 2.8s ease-in-out infinite}@keyframes mg-drift{0%,100%{transform:translateX(0)}50%{transform:translateX(12px)}}.mg-cloud{animation:mg-drift 9s ease-in-out infinite}@media (prefers-reduced-motion:reduce){.mg-pop,.mg-float,.mg-cloud{animation:none}}/*pp-calm*/main{scrollbar-width:none}main::-webkit-scrollbar{display:none}main[style*="mask-image"]::after{content:"";display:block;flex-shrink:0;height:16px}.mg-float,.mg-cloud,.pp-shake,.pp-flick,.pp-tw,.pp-twinkle,.pp-fly,.pp-steam,.pp-ring,.pp-bob,.pp-rays{animation:none!important}.pp-conf{animation-iteration-count:1!important;animation-fill-mode:forwards!important}.pp-claim{animation-iteration-count:3!important}a[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:active,button[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:not(:disabled):active{transform:scale(.97)!important;filter:brightness(.95)!important}/*pp-mainfix*/main[style*="overflow-y: auto"]>*{flex-shrink:0}

